Create Table Mng_Cont                                   -- دليل المتعاملين
( Id         BIGINT AUTO_INCREMENT,                                    -- مفتاح رئيسي
  Num        VARCHAR(15),                            -- الرقم
  Title      VARCHAR(15),                            -- Titel
  Name       VARCHAR(200) NOT NULL,                  -- الاسم
  LName      VARCHAR(200),                           -- الاسم القانوني
  Owner      VARCHAR(200),                           -- اسم المالك
  Contact    VARCHAR(200),                           -- اسم شخص الاتصال
  Cust_Id    BIGINT,                                    -- مفتاح الزبون
  Vend_Id    BIGINT,                                    -- مفتاح المورد
  Status_Id  BIGINT Default 1,                          -- الحالة
  BlnMod_Id  BIGINT Default 1,                          -- نوع الرصيد
  Type_Id    BIGINT Default 0,                          -- نوع المتعامل
  Spc1_Id    BIGINT Default 0,                          -- التصنيف 1
  Spc2_Id    BIGINT Default 0,                          -- التصنيف 2
  Spc3_Id    BIGINT Default 0,                          -- التصنيف 3
  Spc4_Id    BIGINT Default 0,                          -- التصنيف 4
  Spc5_Id    BIGINT Default 0,                          -- التصنيف 5
  Spc6_Id    BIGINT Default 0,                          -- التصنيف 6
  Spc7_Id    BIGINT Default 0,                          -- التصنيف 7
  Spc8_Id    BIGINT Default 0,                          -- التصنيف 8
  Spc9_Id    BIGINT Default 0,                          -- التصنيف 9
  Spc0_Id    BIGINT Default 0,                          -- التصنيف 10
  dLmt       SMALLINT Default -1,                         -- أيام الدين
  nLmt       DECIMAL(25,2) Default -1,                      -- حد الدين
  Repr_Id    BIGINT,                                    -- مندوب المبيعات
  Cost_Id    BIGINT,                                    -- مركز الكلفة
  AccDbt_Id  BIGINT,                                    -- الحساب المدين
  AccCrd_Id  BIGINT,                                    -- الحساب الدائن
  Phone      VARCHAR(50),                            -- الهاتف
  Mobile     VARCHAR(50),                            -- الموبايل
  Fax        VARCHAR(50),                            -- الفاكس
  POBox      VARCHAR(50),                            -- صندوق البريد
  PCode      VARCHAR(50),                            -- الرمز البريدي
  Email      VARCHAR(50),                            -- البريد الالكتروني
  Website    VARCHAR(50),                            -- الموقع الالكتروني
  Address    VARCHAR(200),                           -- العنوان
  Rem        VARCHAR(250),                           -- ملاحظات
  Ins_User   BIGINT, Ins_Date     DATETIME,
  Upd_User   BIGINT, Upd_Date     DATETIME,
  CONSTRAINT Mng_Cont_PK         PRIMARY KEY (Id  ),
  CONSTRAINT Mng_Cont_Num_UK     Unique      (Num ),
  CONSTRAINT Mng_Cont_Name_UK    Unique      (Name),
  CONSTRAINT Mng_Cont_Mobile_UK  Unique      (Mobile ),
  CONSTRAINT Mng_Cont_Cust_UK    Unique      (Cust_Id),
  CONSTRAINT Mng_Cont_Vend_UK    Unique      (Vend_Id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

